        $middleware = $this->middleware(['security.jwt.verify.publickey.location' => 'http://jwks'], $cache, $context, $client);

        $prevCookie = $_COOKIE;
        $prevGet = $_GET;
        unset($_COOKIE['Authorization']);
        $_GET['Authorization'] = $token;

        try {
            /*
