    public function testRejectsTokenWhoseKidNamesAnotherPublishedKey(): void
    {
        $_SERVER['REQUEST_URI'] = '/';
        $_SERVER['SERVER_NAME'] = 'host';
        $_SERVER['REMOTE_ADDR'] = '127.0.0.1';
        $signing = JWKFactory::createRSAKey(1024, ['use' => 'sig', 'alg' => 'RS256', 'kid' => 'k1']);
        $other = JWKFactory::createRSAKey(1024, ['use' => 'sig', 'alg' => 'RS256', 'kid' => 'k2']);
        $jwks = json_encode(['keys' => [$signing->jsonSerialize(), $other->jsonSerialize()]], JSON_THROW_ON_ERROR);
        $response = $this->createStub(ResponseInterface::class);
        $response->method('getBody')->willReturn($this->stream($jwks));
        $client = $this->createStub(ClientInterface::class);
        $client->method('sendRequest')->willReturn($response);
        $cache = new ArrayCache(['jwks.verify.publickey' => $jwks]);
        $middleware = $this->middleware(['security.jwt.verify.publickey.location' => 'http://jwks'], $cache, $this->createStub(Context::class), $client);
        $token = (new CompactSerializer())->serialize((new JWSBuilder(new AlgorithmManager([new RS256()])))->create()
            ->withPayload(json_encode(['sub' => 'user', 'iss' => 'issuer', 'azp' => 'app', 'nbf' => time() - 10, 'exp' => time() + 1000], JSON_THROW_ON_ERROR))
            ->addSignature($signing, ['alg' => 'RS256', 'kid' => 'k2', 'typ' => 'at+jwt'])
            ->build(), 0);

        $this->expectException(UnauthorizedException::class);
        $middleware($this->request('Bearer ' . $token), $this->handler());
    }

    public function testIgnoresVerificationsCachedBeforeTheCacheVersion(): void
    {
        $_SERVER['REQUEST_URI'] = '/';
        $_SERVER['SERVER_NAME'] = 'host';
        $_SERVER['REMOTE_ADDR'] = '127.0.0.1';
        $key = JWKFactory::createRSAKey(1024, ['use' => 'sig', 'alg' => 'RS256', 'kid' => 'k1']);
        // Issued and cached as authenticated before EP-04: no kid, `typ: Bearer` in the payload.
        $token = $this->jwt(['sub' => 'user', 'typ' => 'Bearer', 'azp' => 'app', 'nbf' => time() - 10, 'exp' => time() + 1000], $key, null, false);
        $cache = new ArrayCache([
            "verify_access_{$token}" => json_encode([[], ['id' => 'user', 'tenant' => 'main'], null]),
            "verify_access_v2_{$token}" => json_encode([[], ['id' => 'user', 'tenant' => 'main'], null, null]),
            'jwks.verify.publickey' => json_encode(['keys' => [$key->jsonSerialize()]], JSON_THROW_ON_ERROR),
        ]);
        $context = $this->createMock(Context::class);
        $context->expects($this->never())->method('setSecurityContext');
        $middleware = $this->middleware(['security.jwt.verify.publickey.location' => 'http://jwks'], $cache, $context);

        $this->expectException(UnauthorizedException::class);
        $middleware($this->request('Bearer ' . $token), $this->handler());
    }

    public function testAcceptsAccessToken(): void
    {
        $this->assertTrue($this->authenticates(fn ($key, $claims) => $this->jwt($claims, $key)));
    }

    /**
     * Runs the middleware with a signed, otherwise valid token built by $token(key, claims).
     */
    private function authenticates(\Closure $token, array $config = []): bool
    {
        $_SERVER['REQUEST_URI'] = '/';
        $_SERVER['SERVER_NAME'] = 'host';
        $_SERVER['REMOTE_ADDR'] = '127.0.0.1';
        $key = JWKFactory::createRSAKey(1024, ['use' => 'sig', 'alg' => 'RS256', 'kid' => 'k1']);
        $claims = $this->claims();
        $cache = new ArrayCache(['jwks.verify.publickey' => json_encode(['keys' => [$key->jsonSerialize()]], JSON_THROW_ON_ERROR)]);
        $context = $this->createStub(Context::class);
        $middleware = $this->middleware(['security.jwt.verify.publickey.location' => 'http://jwks', ...$config], $cache, $context);
        try {
            $middleware($this->request('Bearer ' . $token($key, $claims)), $this->handler());
            return true;
        } catch (UnauthorizedException) {
            return false;
        }
    }

    public function testVerifyAuthSuccessFlow(): void
    {
        /*
         * Arrange: create a valid JWT and JWKS payload.
         */
        $_SERVER['REQUEST_URI'] = '/';
        $_SERVER['SERVER_NAME'] = 'host';
        $_SERVER['REMOTE_ADDR'] = '127.0.0.1';
        $now = time();
        $key = JWKFactory::createRSAKey(1024, ['use' => 'sig', 'alg' => 'RS256', 'kid' => 'k1']);
        $jwks = json_encode(['keys' => [$key->jsonSerialize()]], JSON_THROW_ON_ERROR);
        $token = $this->jwt([
            'sub' => 'user',
            'name' => 'User',
            'email' => 'user@example.com',
            'iss' => self::ISSUER,
            'aud' => 'aud1',
            'azp' => 'app',
            'jti' => 'jti-1',
            'nbf' => $now - 10,
            'exp' => $now + 1000,
            'tenant' => 'main',
            'realm_access' => ['roles' => ['admin']]
        ], $key);

        $cache = new ArrayCache([
            'jwks.verify.publickey' => $jwks
        ]);
        $context = $this->createMock(Context::class);
        $context->expects($this->once())
            ->method('setSecurityContext')
            ->with($this->isInstanceOf(\Civi\Lughauth\Shared\Security\Connection::class), $this->isInstanceOf(Identity::class));

        $middleware = $this->middleware([
            'security.jwt.verify.publickey.location' => 'http://jwks',
            'security.jwt.verify.issuer' => self::ISSUER,
            'security.jwt.verify.audiences' => 'aud1',
            'security.jwt.verify.path.roles' => 'realm_access/roles'
        ], $cache, $context);

        /*
         * Act: handle the request with the valid token.
         */
        $response = $middleware($this->request('Bearer ' . $token), $this->handler());

        /*
         * Assert: verify the request succeeds.
         */
        $this->assertSame(200, $response->getStatusCode());
    }

